std::string getSensorName(std::string Str)
{
    std::string sensorName;

    size_t pos = Str.find("/");

    while (pos != std::string::npos)
    {
        sensorName=Str.substr(0, pos);
        Str.erase(Str.begin(), Str.begin() + pos + 1);
        pos = Str.find("/");
    }
    sensorName=Str.substr(0,pos);
    return sensorName;
}

dbusPropVariant getDbusProperty(const std::string& service,
                                   const std::string& objPath,
                                   const std::string& interface,
                                   const std::string& property)
{
    dbusPropVariant Value;
    auto bus = sdbusplus::bus::new_default();
    try
    {
        auto method = bus.new_method_call(service.c_str(), objPath.c_str(),
                                          "org.freedesktop.DBus.Properties",
                                          "Get");

        method.append(interface, property);

        auto reply = bus.call(method);
        reply.read(Value);
    }
    catch (const sdbusplus::exception_t& e)
    {
        std::cerr << "Fail to getDbusProperty : " << e.what() << std::endl;
    }
    return Value;
}

void getSensorData(std::vector<amiHandleSensorTable_entry>& data)
{
        // Object Mapper related
    static constexpr const char* objMapperService =
      "xyz.openbmc_project.ObjectMapper";
    static constexpr const char* objMapperPath =
      "/xyz/openbmc_project/object_mapper";
    static constexpr const char* objMapperInterface =
      "xyz.openbmc_project.ObjectMapper";
    auto depth = 0;
    std::string iface = "xyz.openbmc_project.Sensor.Value";
    std::string value = "Value";
    std::string path = "/";

    using GetSubTreeType = std::vector<
    std::pair<std::string,
              std::vector<std::pair<std::string, std::vector<std::string>>>>>;

    GetSubTreeType mapperRead;
    try
    {
        auto bus = sdbusplus::bus::new_default();

        auto mapperCall = bus.new_method_call(objMapperService, objMapperPath,
                                              objMapperInterface, "GetSubTree");

        mapperCall.append(path);
        mapperCall.append(depth);
        mapperCall.append(std::vector<std::string>{iface});

        auto mapperResponse = bus.call(mapperCall);
        mapperResponse.read(mapperRead);
    }
    catch (const sdbusplus::exception_t& e)
    {
        std::cout << "Error in getSensorData" << std::endl ;
    }

    dbusPropVariant datafloatvariant;
    double datafloat;
    int index=1;
    amiHandleSensorTable_entry tmpData;
    std::memset(&tmpData, 0, sizeof(tmpData));
    for (const auto& outerPair : mapperRead) {
        for (const auto& innerPair : outerPair.second) {

            std::string service = innerPair.first.c_str();
            std::string path = outerPair.first.c_str();

            datafloatvariant=getDbusProperty(service,path,iface,value);

            if(auto ptr=std::get_if<double>(&datafloatvariant)){
		datafloat=*ptr;
	    }
	    else{
		datafloat=0;
	    }
	    std::string name = getSensorName(path);
	    tmpData.sensorIndex=index++;
	    std::strncpy(tmpData.sensorName, name.data(), sizeof(tmpData.sensorName)-1);
	    tmpData.sensorValue=datafloat;
	    data.push_back(tmpData);
	    std::memset(&tmpData, 0, sizeof(tmpData));
        }
    }
}

void AddToSensorInstances(struct amiHandleSensorTable_entry *sensorInst)
{
    struct amiHandleSensorTable_entry *ptr = NULL;
    if (sensorData_head == NULL)
    {
        sensorData_head = sensorInst;
    }
    else
    {
        ptr = sensorData_head;
        while (ptr->next != NULL)
	{
            ptr = ptr->next;
	}
        ptr->next = sensorInst;
    }
}


int
sensorTable_load(netsnmp_cache *cache, void *vmagic)
{
    struct amiHandleSensorTable_entry *table_entry = NULL;

    if(0)
    {
        cache=cache;
        vmagic=vmagic;
    }

    std::vector<amiHandleSensorTable_entry> sensorData;
    getSensorData(sensorData);

    for(auto it=sensorData.begin();it!=sensorData.end();it++)
    {
        table_entry = (struct amiHandleSensorTable_entry *) calloc(1, sizeof(struct amiHandleSensorTable_entry));
        table_entry->sensorIndex = it->sensorIndex;
        std::strncpy ( table_entry->sensorName , it->sensorName, (sizeof(it->sensorName)-1));
        table_entry->sensorValue  = it->sensorValue;
        table_entry->next = NULL;

        /*Adds the current sensor table as instance.*/
        AddToSensorInstances(table_entry);
    }

    return 0;
}

