/** handles requests for the netSnmpAmiSensorTable table */
int
handler_netSnmpAmiSensorTable(
    netsnmp_mib_handler               *handler,
    netsnmp_handler_registration      *reginfo,
    netsnmp_agent_request_info        *reqinfo,
    netsnmp_request_info              *requests) {

    netsnmp_request_info       *request=NULL;
    netsnmp_table_request_info *table_info=NULL;
    struct amiHandleSensorTable_entry *table_entry=NULL;

    if(0)
    {
        handler = handler;
        reginfo = reginfo;
    }

    if (reqinfo->mode == MODE_GET) {

        for (request=requests; request; request=request->next)
        {
            table_entry = (struct amiHandleSensorTable_entry *)
                                   netsnmp_extract_iterator_context(request);
            table_info = netsnmp_extract_table_info(request);

            if (table_entry == NULL)
            {
                netsnmp_set_request_error(reqinfo, request, SNMP_NOSUCHINSTANCE);
                continue;
            }

            switch (table_info->colnum)
            {
              case COLUMN_SENSORINDEX:
                snmp_set_var_typed_value( request->requestvb, ASN_INTEGER,
                                          (u_char *)&table_entry->sensorIndex,
                                          sizeof(table_entry->sensorIndex));
                break;
              case COLUMN_SENSORNAME:
                snmp_set_var_typed_value( request->requestvb, ASN_OCTET_STR,
                                          (u_char *)table_entry->sensorName,
                                          std::strlen(table_entry->sensorName));
                break;
              case COLUMN_SENSORVALUE:
                snmp_set_var_typed_value( request->requestvb, ASN_OPAQUE_DOUBLE,
                                            (u_char *)&table_entry->sensorValue,
					    sizeof(table_entry->sensorValue));
                break;
              default:
                netsnmp_set_request_error(reqinfo, request, SNMP_NOSUCHOBJECT);
                break;
             }
          }
    }

    return SNMP_ERR_NOERROR;
}

